+            builder.nnTopology(namenodeTopology);
+        }
+
+        MiniDFSCluster dfs = builder.build();
+
+        // Configure contents of the filesystem
+        org.apache.hadoop.fs.Path esUserPath = new org.apache.hadoop.fs.Path("/user/elasticsearch");
+
+        FileSystem fs;
+        if (haEnabled) {
